-- git-svc: repositories and the event outbox in the git_svc schema
-- Git keeps objects and refs on disk; these tables hold metadata only.
-- The source of truth is git2's migrations/. git2-codeplane keeps an
-- identical copy for its tests.
CREATE SCHEMA IF NOT EXISTS git_svc;

-- id is a random (v4) UUID generated by git-svc: its first two hex
-- characters pick the directory shard of the repository on disk.
-- name keeps the case it was created with; uniqueness is case-insensitive
-- through the index below. deleted_at is NULL while the repository is live;
-- deleted rows are kept.
CREATE TABLE IF NOT EXISTS git_svc.repositories (
    id             UUID        PRIMARY KEY,
    owner_id       UUID        NOT NULL,
    name           TEXT        NOT NULL,
    default_branch TEXT        NOT NULL,
    description    TEXT        NOT NULL DEFAULT '',
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at     TIMESTAMPTZ
);

-- One live repository per owner and name, compared case-insensitively.
-- Deleted rows are excluded, so a name can be reused right after a delete.
CREATE UNIQUE INDEX IF NOT EXISTS repositories_owner_name_live_uq
    ON git_svc.repositories (owner_id, lower(name))
    WHERE deleted_at IS NULL;

-- Domain events, written in the same transaction as the change they
-- describe. A relay delivers pending rows at least once.
--   event_id:     lets consumers drop duplicates
--   event_type:   full protobuf message name, e.g. 'git.v1.RepositoryCreated'
--   payload:      the event message in canonical protobuf JSON
--   published_at: NULL until the relay has delivered the event
CREATE TABLE IF NOT EXISTS git_svc.outbox (
    id             BIGSERIAL   PRIMARY KEY,
    event_id       UUID        NOT NULL,
    aggregate_type TEXT        NOT NULL,
    aggregate_id   UUID        NOT NULL,
    event_type     TEXT        NOT NULL,
    payload        JSONB       NOT NULL,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    published_at   TIMESTAMPTZ,
    CONSTRAINT outbox_event_id_key UNIQUE (event_id)
);

-- Lets the relay find pending events without scanning delivered ones.
CREATE INDEX IF NOT EXISTS outbox_unpublished_idx
    ON git_svc.outbox (id)
    WHERE published_at IS NULL;
